const express = require('express');
require('reflect-metadata');
const { plainToInstance } = require('class-transformer');
const { validateOrReject, IsUUID, IsString, Length, Matches } = require('class-validator');
const mqtt = require('mqtt');
const knex = require('knex')({ client: 'pg', connection: process.env.DATABASE_URL });

const app = express();
app.use(express.json());
const mqttClient = mqtt.connect(process.env.MQTT_BROKER_URL);

class UpdateLockPinDto {
  @IsUUID()
  lockId;

  @IsString()
  @Length(4, 8)
  @Matches(/^\d+$/)
  newPinCode;

  @IsString()
  pinLabel;
}

const validateLockDto = async (req, res, next) => {
  const dto = plainToInstance(UpdateLockPinDto, req.body);
  try {
    await validateOrReject(dto);
    req.lockDto = dto;
    next();
  } catch (e) {
    res.status(400).json({ error: 'PIN update payload rejected' });
  }
};

app.put('/api/iot/locks/pin', validateLockDto, async (req, res) => {
  if (!req.user || !req.user.id) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { lockId, newPinCode, pinLabel } = req.lockDto;

  // Confirm that lockId is registered to a property owned/leased by caller
  const lockAccess = await knex('property_locks')
    .join('user_properties', 'property_locks.property_id', 'user_properties.property_id')
    .where({
      'property_locks.id': lockId,
      'user_properties.user_id': req.user.id
    })
    .first();

  if (!lockAccess) {
    return res.status(403).json({ error: 'Forbidden: unauthorized to configure this smart lock' });
  }

  mqttClient.publish(
    `mesh/smartlocks/${lockId}/commands/set_pin`,
    JSON.stringify({ pin: newPinCode, label: pinLabel, timestamp: Date.now() }),
    { qos: 1 }
  );

  res.json({ success: true, lockId, message: 'Door PIN updated' });
});

app.listen(7003);
